function stone(key,i){var src=SPR.img["stone_"+key];if(!src){var h=hex(key);src=JFAM[key]?shadeSrc(JFAM[key],null,1):h?shadeSrc("own",h,1):SPR.img.stone_clear;}return strip(src,i);}
